insert into public.knowledge_sources (key, title, issuer, document, url, jurisdiction, tax_year, revision, topics, summary, key_facts, eligibility, verified_on, status, prepared_by) values
  ('irs-pub-583', 'Publication 583 (12/2024), Starting a Business and Keeping Records', 'IRS', 'Publication 583', 'https://www.irs.gov/publications/p583', 'US-federal', null, 'Revised: December 2024; Page Last Reviewed or Updated: 30-Apr-2026', array['business-structures','deductions','self-employment-tax']::text[], 'An introductory IRS guide for new business owners. It explains the common federal tax forms of business (sole proprietorship, partnership, corporation, S corporation, LLC), getting an EIN, which federal taxes apply, how start-up costs are treated, and how long to keep records.', '[{"fact": "You can elect to deduct a limited amount of business start-up costs and, separately, organizational costs; each amount shrinks once the costs exceed a threshold.", "figure": "$5,000 of business start-up costs and up to $5,000 of organizational costs; reduced by the amount ... costs exceed $50,000", "where": "Business Start-Up Costs"}, {"fact": "An LLC can be classified for federal tax purposes as a partnership, a corporation, or an entity disregarded from its owner.", "figure": null, "where": "Determining Which Type of Business to Use (Limited liability company)"}, {"fact": "The general period of limitations for income tax returns (the time to amend or for the IRS to assess) is 3 years; it is 6 years if more than 25% of gross income was left off the return.", "figure": "3 years; 6 years", "where": "Table 3. Period of Limitations"}, {"fact": "Claims for a loss from worthless securities or a bad debt deduction have a longer limitations period.", "figure": "7 years", "where": "Table 3. Period of Limitations"}, {"fact": "Employers must keep employment tax records for a minimum period after the tax becomes due or is paid, whichever is later.", "figure": "at least 4 years", "where": "How Long To Keep Records"}]'::jsonb, 'Applies to people starting a U.S. business of any form; it covers tax considerations only (not state legal formation rules). It is a revision-dated publication (December 2024) rather than an annual tax-year edition, so year-specific dollar amounts should be checked against current-year publications.', '2026-11-26', 'draft', 'peace'),
  ('irs-pub-334', 'Publication 334 (2025), Tax Guide for Small Business', 'IRS', 'Publication 334', 'https://www.irs.gov/publications/p334', 'US-federal', 2025, 'For use in preparing 2025 Returns; Page Last Reviewed or Updated: 30-Apr-2026', array['business-structures','deductions','self-employment-tax','depreciation']::text[], 'The main IRS guide for sole proprietors and single-member LLC owners who file Schedule C. It covers filing and paying business taxes, accounting periods and methods, business income, the chapter on business expenses (car and truck, travel and meals, depreciation, de minimis safe harbor), and self-employment tax.', '[{"fact": "Self-employment (SE) tax combines social security and Medicare parts.", "figure": "15.3% (12.4% social security tax plus 2.9% Medicare tax)", "where": "Chapter 1, Filing and Paying Business Taxes - Self-Employment (SE) Tax"}, {"fact": "Only earnings up to the annual wage base are subject to the social security part of SE tax for 2025; the Medicare part has no cap.", "figure": "$176,100", "where": "What''s New for 2025 (Maximum net earnings); Chapter 1 - Self-Employment (SE) Tax"}, {"fact": "Business standard mileage rate for 2025, with the 2026 rate previewed.", "figure": "70 cents a mile; 72.5 cents a mile", "where": "What''s New for 2025 / What''s New for 2026 (Standard mileage rate); Chapter 8 - Car and Truck Expenses"}, {"fact": "Business meal deductions are generally limited to half of the cost.", "figure": "50%", "where": "Reminders (Business meal expense); Chapter 8 - Travel and Meals"}, {"fact": "Section 179 maximum deduction for 2025.", "figure": "$2,500,000", "where": "Chapter 8, Business Expenses - Depreciation"}, {"fact": "The de minimis safe harbor lets a business deduct small tangible property purchases instead of capitalizing them, with a higher per-item/invoice limit for businesses with an applicable financial statement.", "figure": "$2,500 per item or invoice; $5,000 per item or invoice", "where": "Chapter 8, Business Expenses - De Minimis Safe Harbor for Tangible Property"}]'::jsonb, 'Aimed at sole proprietors and statutory employees; partnerships and corporations are pointed to other publications. The 2026 edition was not yet posted on the date checked; the 2025 edition is the latest.', '2026-11-26', 'draft', 'peace'),
  ('irs-i2553', 'Instructions for Form 2553 (12/2020)', 'IRS', 'Form 2553 Instructions', 'https://www.irs.gov/instructions/i2553', 'US-federal', null, 'Revised: 12/2020; Page Last Reviewed or Updated: 30-Apr-2026', array['business-structures']::text[], 'Explains how a corporation, or an entity eligible to be treated as a corporation such as an LLC, elects S corporation status by filing Form 2553. It lists the eligibility tests, the filing deadline, and the relief procedures for late elections.', '[{"fact": "An electing corporation can have only a limited number of shareholders (spouses and family members can be counted as one).", "figure": "no more than 100 shareholders", "where": "General Instructions - Who May Elect"}, {"fact": "The corporation must have only one class of stock (differences in voting rights alone are disregarded).", "figure": null, "where": "General Instructions - Who May Elect"}, {"fact": "To take effect for a given tax year, the election is generally due shortly after that year begins (or at any time during the preceding tax year).", "figure": "No more than 2 months and 15 days after the beginning of the tax year", "where": "General Instructions - When To Make the Election"}, {"fact": "Simplified relief for a late election may be available when reasonable cause is shown and the form is filed within a set window.", "figure": "within 3 years and 75 days", "where": "General Instructions - Relief for Late Elections (Rev. Proc. 2013-30)"}]'::jsonb, 'Applies to domestic corporations and eligible domestic entities meeting the shareholder, stock-class, and other tests. The instructions carry a December 2020 revision date; no newer revision was posted on the date checked.', '2026-11-26', 'draft', 'peace'),
  ('sba-choose-business-structure', 'Choose a business structure', 'SBA', null, 'https://www.sba.gov/business-guide/launch-your-business/choose-business-structure', 'US-federal', null, null, array['business-structures']::text[], 'SBA''s plain-language overview of common structures: sole proprietorship, partnerships (LP and LLP), LLC, C corp, S corp, benefit corporation, close corporation, nonprofit, and cooperative. It compares ownership, personal liability, and how each is generally taxed, and notes that S corp and nonprofit are really tax statuses that can apply to other entity types.', '[{"fact": "A sole proprietorship is not a separate entity, so the owner can be personally liable for business debts.", "figure": null, "where": "Review common business structures - Sole proprietorship"}, {"fact": "LLC members are generally considered self-employed and pay self-employment tax on their share of profits.", "figure": null, "where": "Review common business structures - Limited liability company (LLC)"}, {"fact": "C corporation profits can be taxed twice: at the corporate level and again when dividends are paid to shareholders.", "figure": null, "where": "Review common business structures - C corp"}, {"fact": "The SBA comparison table summarizes S corp ownership limits.", "figure": "100 people or fewer; certain trusts and estates; no partnerships, corporations, or non-resident aliens", "where": "Compare business structures (table)"}, {"fact": "The structure choice must be made before registering with the state; later conversion is possible but can have tax consequences.", "figure": null, "where": "Choose a business structure (introduction)"}]'::jsonb, 'General federal-level guidance; state rules on ownership, liability, taxes and filings vary. SBA itself says the comparison table is only a guideline.', '2026-11-26', 'draft', 'peace'),
  ('irs-pub-463', 'Publication 463 (2025), Travel, Gift, and Car Expenses', 'IRS', 'Publication 463', 'https://www.irs.gov/publications/p463', 'US-federal', 2025, 'For use in preparing 2025 Returns; Page Last Reviewed or Updated: 30-Apr-2026', array['deductions','depreciation']::text[], 'Explains which business travel, meal, gift, and transportation (car) expenses can be deducted, the limits that apply, and the records needed to support them. It also covers the standard mileage rate versus actual expenses, car depreciation limits, and employer reimbursement plans.', '[{"fact": "Business meal expenses are generally deductible at a reduced percentage (a higher percentage applies to workers under DOT hours-of-service limits).", "figure": "50% ... 80%", "where": "Chapter 2, Meals and Entertainment - 50% Limit"}, {"fact": "Deductions for business gifts are capped per recipient per year.", "figure": "no more than $25", "where": "Chapter 3, Gifts - $25 limit"}, {"fact": "The 2025 business standard mileage rate.", "figure": "70 cents ($0.70) per mile", "where": "Chapter 4, Transportation - Standard Mileage Rate"}, {"fact": "To use the standard mileage rate for an owned car, you must choose it in the first year the car is available for business use.", "figure": null, "where": "Chapter 4 - Standard Mileage Rate (Choosing the standard mileage rate)"}, {"fact": "First-year depreciation cap for passenger automobiles placed in service in 2025 when bonus (168(k)) depreciation applies.", "figure": "$20,200", "where": "What''s New - Depreciation limits on cars, trucks, and vans"}]'::jsonb, 'Covers self-employed people and employers (and employees in the limited cases still allowed). Unreimbursed employee travel is generally not deductible as a miscellaneous itemized deduction. The 2026 edition was not yet posted on the date checked.', '2026-11-26', 'draft', 'peace'),
  ('irs-pub-587', 'Publication 587 (2025), Business Use of Your Home', 'IRS', 'Publication 587', 'https://www.irs.gov/publications/p587', 'US-federal', 2025, 'For use in preparing 2025 Returns; Page Last Reviewed or Updated: 30-Apr-2026', array['deductions']::text[], 'Explains when part of a home qualifies for a business-use deduction and how to figure it using either actual expenses or the simplified method. It includes special rules for storage of inventory and daycare facilities.', '[{"fact": "The space must generally be used exclusively and regularly for business, for example as the principal place of business.", "figure": null, "where": "Qualifying for a Deduction - Exclusive Use / Regular Use"}, {"fact": "The simplified method multiplies a prescribed rate by the business-use area, with a cap on square footage.", "figure": "$5, the prescribed rate ... limited to 300 square feet", "where": "Using the Simplified Method"}, {"fact": "The exclusive-use test does not apply to certain inventory/product-sample storage and to daycare facilities.", "figure": null, "where": "Exceptions to Exclusive Use"}]'::jsonb, 'Applies to self-employed individuals and others with a qualifying home office; the deduction is limited by the business''s income. The 2026 edition was not yet posted on the date checked.', '2026-11-26', 'draft', 'peace'),
  ('irs-pub-15b', 'Publication 15-B (2026), Employer''s Tax Guide to Fringe Benefits', 'IRS', 'Publication 15-B', 'https://www.irs.gov/publications/p15b', 'US-federal', 2026, 'For use in 2026; Page Last Reviewed or Updated: 30-Apr-2026', array['deductions','payroll']::text[], 'An employer guide to the federal tax treatment of fringe benefits such as health benefits, educational assistance, dependent care, transportation, and de minimis benefits. It explains which benefits can be excluded from wages and the limits on those exclusions.', '[{"fact": "Monthly exclusion for qualified parking and for transit passes/commuter vehicle transportation in 2026.", "figure": "$340", "where": "What''s New - Qualified parking exclusion and commuter transportation benefit"}, {"fact": "Health FSA salary-reduction contribution cap for plan years beginning in 2026.", "figure": "$3,400", "where": "What''s New; Cafeteria Plans"}, {"fact": "Dependent care assistance exclusion raised for 2026.", "figure": "from $5,000 to $7,500 ($2,500 to $3,750 for married filing separately)", "where": "What''s New - Dependent care assistance exclusion from wages"}, {"fact": "Employer-provided educational assistance (including student loan payments) exclusion made permanent.", "figure": "$5,250", "where": "What''s New - Employer payments of student loans; Table 2-1"}, {"fact": "For amounts after 2025, employers can no longer deduct food and beverages provided through qualifying on-premises eating facilities or for the employer''s convenience.", "figure": null, "where": "What''s New - Employer''s meal deduction"}]'::jsonb, 'For employers providing benefits to employees; special rules apply to more-than-2% S corporation shareholders and to partners.', '2026-11-26', 'draft', 'peace'),
  ('irs-standard-mileage-rates', 'Standard mileage rates', 'IRS', null, 'https://www.irs.gov/tax-professionals/standard-mileage-rates', 'US-federal', 2026, 'Page Last Reviewed or Updated: 28-Jul-2026', array['deductions']::text[], 'IRS reference page listing the optional standard mileage rates by period for business, charitable, medical and military moving use. For 2026 it shows two periods because the IRS raised the business and medical/moving rates mid-year.', '[{"fact": "Business rate for July 1 - Dec. 31, 2026.", "figure": "76 cents/mile", "where": "2026 mileage rates (July 1 - Dec. 31)"}, {"fact": "Business rate for Jan. 1 - June 30, 2026.", "figure": "72.5", "where": "Mileage rates for all years table (cents/mile), source IR-2025-128"}, {"fact": "Medical / military moving rate: 20.5 for Jan. 1 - June 30, 2026, then 23.5 from July 1, 2026; charity rate unchanged.", "figure": "23.5 cents/mile; Charities: 14 cents/mile", "where": "2026 mileage rates (July 1 - Dec. 31)"}, {"fact": "The table cites IR-2026-29 as the source for the July 1 change (linked to Internal Revenue Bulletin 2026-29, which contains Announcement 2026-11 modifying Notice 2026-10).", "figure": "IR-2026-29", "where": "Mileage rates for all years table"}]'::jsonb, 'The standard mileage rate is optional; actual expenses can be used instead, subject to first-year election rules. The charitable rate is fixed by statute.', '2026-11-26', 'draft', 'peace'),
  ('irs-newsroom-2026-mileage', 'IRS sets 2026 business standard mileage rate at 72.5 cents per mile, up 2.5 cents', 'IRS', 'IR-2025-128 (Notice 2026-10)', 'https://www.irs.gov/newsroom/irs-sets-2026-business-standard-mileage-rate-at-725-cents-per-mile-up-25-cents', 'US-federal', 2026, 'IR-2025-128, Dec. 29, 2025', array['deductions']::text[], 'IRS news release announcing the standard mileage rates effective January 1, 2026. Note that these rates were later revised upward for July 1 - December 31, 2026 (see the Standard mileage rates page).', '[{"fact": "Business rate beginning Jan. 1, 2026.", "figure": "72.5 cents per mile", "where": "News release body"}, {"fact": "Medical and qualifying military/intelligence-community moving rate beginning Jan. 1, 2026.", "figure": "20.5 cents per mile", "where": "News release body"}, {"fact": "Charitable rate (set by statute) unchanged from 2025.", "figure": "14 cents per mile", "where": "News release body"}, {"fact": "Rates apply to fully-electric and hybrid vehicles as well as gas and diesel vehicles; an owned vehicle must use the standard rate in its first business year to use it later.", "figure": null, "where": "News release body"}]'::jsonb, 'Superseded for the second half of 2026: the business rate became 76 cents and medical/moving 23.5 cents from July 1, 2026. News items may not be updated after release.', '2026-11-26', 'draft', 'peace'),
  ('irs-pub-15', 'Publication 15 (2026), (Circular E), Employer''s Tax Guide', 'IRS', 'Publication 15 (Circular E)', 'https://www.irs.gov/publications/p15', 'US-federal', 2026, 'For use in 2026; Page Last Reviewed or Updated: 30-Apr-2026', array['payroll']::text[], 'The core IRS employer guide on withholding, depositing, reporting, and paying federal income tax, social security and Medicare taxes, and FUTA tax. It covers who is an employee, deposit schedules, Forms 941/944/940, and correcting errors.', '[{"fact": "Social security tax rate (each for employer and employee) and the 2026 wage base.", "figure": "6.2% ... $184,500", "where": "What''s New - Social security and Medicare taxes for 2026; Social Security and Medicare Taxes"}, {"fact": "Medicare tax rate, each for employer and employee, with no wage base limit.", "figure": "1.45%", "where": "What''s New; Social Security and Medicare Taxes"}, {"fact": "Additional Medicare Tax withholding starts once an employee''s wages exceed a threshold in a calendar year.", "figure": "0.9% ... in excess of $200,000", "where": "Social Security and Medicare Taxes"}, {"fact": "You are a monthly schedule depositor if taxes reported in the lookback period were at or below a threshold.", "figure": "$50,000 or less", "where": "Section 11, Depositing Taxes"}, {"fact": "FUTA tax for 2026 applies to the first part of each employee''s wages; with the maximum state credit the effective rate is lower.", "figure": "6.0% ... first $7,000 ... 0.6%", "where": "Section 14, Federal Unemployment (FUTA) Tax"}]'::jsonb, 'Applies to employers with employees; agricultural employers use Pub. 51 and supplemental topics are in Pub. 15-A and 15-B. Withholding tables are in Pub. 15-T.', '2026-11-26', 'draft', 'peace'),
  ('irs-pub-15a', 'Publication 15-A (2026), Employer''s Supplemental Tax Guide', 'IRS', 'Publication 15-A', 'https://www.irs.gov/publications/p15a', 'US-federal', 2026, 'For use in 2026; Page Last Reviewed or Updated: 30-Apr-2026', array['payroll']::text[], 'Supplements Pub. 15 with specialized employment tax topics, most notably how to tell an employee from an independent contractor using the common-law rules. It also covers statutory employees and nonemployees, sick pay, and various types of compensation.', '[{"fact": "Worker classification under the common-law rules looks at three categories of evidence.", "figure": null, "where": "Section 2, Employee or Independent Contractor? - Common-Law Rules (behavioral control, financial control, type of relationship)"}, {"fact": "A business can ask the IRS to determine a worker''s status.", "figure": "Form SS-8", "where": "Section 2 - Common-Law Rules"}, {"fact": "Misclassifying an employee without a reasonable basis makes the business liable for employment taxes for that worker.", "figure": null, "where": "Section 1 - Misclassification of Employees"}, {"fact": "Social security wage base for 2026 (repeated from Pub. 15).", "figure": "$184,500", "where": "What''s New"}, {"fact": "Alternative withholding methods and tables were moved out of Pub. 15-A into Pub. 15-T.", "figure": null, "where": "What''s New - 2026 withholding tables"}]'::jsonb, 'For employers needing detail beyond Pub. 15; classification is fact-specific.', '2026-11-26', 'draft', 'peace'),
  ('irs-pub-560', 'Publication 560 (2025), Retirement Plans for Small Business', 'IRS', 'Publication 560', 'https://www.irs.gov/publications/p560', 'US-federal', 2025, 'For use in preparing 2025 Returns; Page Last Reviewed or Updated: 30-Apr-2026', array['retirement-plans']::text[], 'Explains SEP, SIMPLE, and qualified (including 401(k)) retirement plans for small employers and self-employed people: setting them up, contribution and deduction limits, and reporting. The What''s New section gives both 2025 and 2026 limits.', '[{"fact": "SEP contributions for an employee are capped at the lesser of a percentage of compensation or a dollar amount for 2025.", "figure": "lesser of 25% of the employee''s compensation or $70,000", "where": "Chapter 2, SEPs - Contribution Limits"}, {"fact": "Elective deferral limit (401(k), SARSEP, 403(b), 457(b)).", "figure": "$23,500 for 2025 and $24,500 for 2026", "where": "What''s New - Elective deferral limits"}, {"fact": "Defined contribution plan annual addition limit.", "figure": "$70,000 for 2025 and increases to $72,000 for 2026", "where": "What''s New - Defined contribution limits"}, {"fact": "SIMPLE plan salary reduction limit.", "figure": "$16,500 for 2025 and increases to $17,000 for 2026", "where": "What''s New - SIMPLE plan salary reduction contribution limits"}, {"fact": "Higher catch-up contributions are allowed in the years a participant turns 60-63.", "figure": "$11,250", "where": "What''s New - Higher catch-up contribution limit for ages 60 to 63"}, {"fact": "Only employers with a limited number of employees earning a minimum amount can set up a SIMPLE IRA plan.", "figure": "100 or fewer employees who received $5,000 or more", "where": "Chapter 3, SIMPLE Plans - Who Can Set up a SIMPLE IRA Plan?"}, {"fact": "Review note from Peace: Pub 560 lists the higher applicable SIMPLE limit as $18,100 for 2025, while IRS news release IR-2025-111 lists $17,600 for 2025 and $18,100 for 2026. Confirm with the IRS before relying on the 2025 figure.", "figure": null, "where": "Cross-check with IR-2025-111"}]'::jsonb, 'Self-employed individuals use 20% of net earnings (not 25%) for their own SEP contribution calculation. The 2026 edition was not yet posted on the date checked. Possible discrepancy: Pub 560 says the higher SIMPLE limit is "$18,100 for 2025", while IR-2025-111 gives $17,600 for 2025 and $18,100 for 2026.', '2026-11-26', 'draft', 'peace'),
  ('irs-newsroom-2026-retirement-limits', '401(k) limit increases to $24,500 for 2026, IRA limit increases to $7,500', 'IRS', 'IR-2025-111 (Notice 2025-67)', 'https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500', 'US-federal', 2026, 'IR-2025-111, Nov. 13, 2025', array['retirement-plans']::text[], 'IRS announcement of the 2026 cost-of-living adjustments for retirement plans and IRAs, with technical details in Notice 2025-67.', '[{"fact": "Employee deferral limit for 401(k), 403(b), governmental 457 plans and TSP.", "figure": "$24,500", "where": "Highlights of changes for 2026"}, {"fact": "Catch-up limit for participants aged 50 and over in those plans, and the age 60-63 higher catch-up.", "figure": "$8,000 ... $11,250", "where": "Highlights of changes for 2026"}, {"fact": "IRA contribution limit and IRA catch-up limit.", "figure": "$7,500 ... $1,100", "where": "Highlights of changes for 2026"}, {"fact": "SIMPLE retirement account limit, and the higher limit for certain applicable SIMPLE plans.", "figure": "$17,000 ... $18,100", "where": "Other phase-out ranges and limitations"}, {"fact": "Roth IRA income phase-out range for singles and heads of household.", "figure": "between $153,000 and $168,000", "where": "Other phase-out ranges and limitations"}]'::jsonb, 'Limits apply to tax year 2026. IRA deduction and Roth phase-outs depend on filing status, income, and workplace plan coverage.', '2026-11-26', 'draft', 'peace'),
  ('irs-newsroom-2027-retirement-limits', '401(k) limit increases to $25,500 for 2027, IRA limit remains $7,500', 'IRS', 'IR-2026-136 (Notice 2026-66)', 'https://www.irs.gov/newsroom/401k-limit-increases-to-25500-for-2027-ira-limit-remains-7500', 'US-federal', 2027, 'IR-2026-136, Nov. 12, 2026', array['retirement-plans']::text[], 'IRS announcement, released before 2027 began, of the retirement plan cost-of-living adjustments for 2027. Included so the library can show the year ahead; technical details are in Notice 2026-66.', '[{"fact": "Employee deferral limit for 401(k), 403(b), governmental 457 plans and TSP in 2027.", "figure": "$25,500", "where": "Highlights of changes for 2027"}, {"fact": "Age 50+ catch-up and the age 60-63 higher catch-up for 2027.", "figure": "$8,500 ... $11,750", "where": "Highlights of changes for 2027"}, {"fact": "IRA limit unchanged for 2027.", "figure": "$7,500", "where": "Highlights of changes for 2027"}, {"fact": "SIMPLE retirement account limit for 2027.", "figure": "$17,500", "where": "Other phase-out ranges and limitations"}]'::jsonb, 'Applies to tax year 2027, not 2026. Shown as forward-looking context.', '2026-11-26', 'draft', 'peace'),
  ('irs-pub-946', 'Publication 946 (2025), How To Depreciate Property', 'IRS', 'Publication 946', 'https://www.irs.gov/publications/p946', 'US-federal', 2025, 'For use in preparing 2025 Returns; Page Last Reviewed or Updated: 30-Apr-2026', array['depreciation']::text[], 'The IRS''s comprehensive depreciation guide covering the section 179 deduction, the special (bonus) depreciation allowance, MACRS, and listed property. The 2025 edition reflects P.L. 119-21 (One Big Beautiful Bill Act) changes and previews 2026 section 179 limits.', '[{"fact": "Section 179 maximum deduction and phase-out threshold for tax years beginning in 2025.", "figure": "$2,500,000 ... exceeds $4,000,000", "where": "What''s New for 2025; Chapter 2 - Dollar Limits"}, {"fact": "Section 179 limits for tax years beginning in 2026.", "figure": "$2,560,000 ... exceeds $4,090,000 ... sport utility vehicles ... $32,000", "where": "What''s New for 2026"}, {"fact": "SUV section 179 cap for 2025.", "figure": "$31,300", "where": "What''s New for 2025"}, {"fact": "100% special depreciation allowance reinstated for certain qualified property acquired and placed in service after January 19, 2025 (an election to use 40% is available for the first tax year ending after that date).", "figure": "100%", "where": "What''s New for 2025"}, {"fact": "Property acquired before January 20, 2025 and placed in service in 2025 is generally limited to the phased-down rate.", "figure": "40%", "where": "What''s New for 2025 - Phase down of special depreciation allowance"}]'::jsonb, 'Applies to businesses and investors depreciating property. Section 179 does not apply to the business part of a home; the deduction can be limited by business income. The 2026 edition was not yet posted on the date checked.', '2026-11-26', 'draft', 'peace'),
  ('irs-i4562', 'Instructions for Form 4562 (2025)', 'IRS', 'Form 4562 Instructions', 'https://www.irs.gov/instructions/i4562', 'US-federal', 2025, '2025; Page Last Reviewed or Updated: 30-Apr-2026', array['depreciation']::text[], 'Line-by-line instructions for Form 4562, used to claim depreciation, the section 179 deduction, amortization, and to report listed property such as vehicles. The What''s New section summarizes 2025 section 179 and bonus depreciation changes.', '[{"fact": "Section 179 limit, phase-out threshold, and SUV cap for tax years beginning in 2025.", "figure": "$2,500,000 ... $4,000,000 ... $31,300", "where": "What''s New"}, {"fact": "Bonus depreciation reinstated at 100% for certain property acquired and placed in service after January 19, 2025; earlier-acquired property is limited to 40% (60% for long production period property and certain aircraft).", "figure": "100% ... 40% ... 60%", "where": "What''s New"}, {"fact": "Domestic research or experimental expenditures paid or incurred in tax years beginning in 2025 can be deducted currently under new section 174A (with elections to amortize).", "figure": null, "where": "What''s New"}, {"fact": "Form 4562 is required for depreciation on property placed in service during 2025, any section 179 deduction, and depreciation on any vehicle or other listed property.", "figure": null, "where": "General Instructions - Who Must File"}]'::jsonb, 'Applies to 2025 tax year returns. The 2026 instructions were not yet posted on the date checked.', '2026-11-26', 'draft', 'peace'),
  ('irs-i8995', 'Instructions for Form 8995 (2025)', 'IRS', 'Form 8995 Instructions', 'https://www.irs.gov/instructions/i8995', 'US-federal', 2025, '2025; Page Last Reviewed or Updated: 30-Apr-2026', array['qbi']::text[], 'Instructions for the simplified worksheet used to figure the qualified business income (QBI) deduction when taxable income is at or below the threshold. It explains what counts as QBI, REIT dividends and PTP income.', '[{"fact": "The QBI deduction can be up to a percentage of net QBI from a trade or business (not a C corporation), plus the same percentage of qualified REIT dividends and PTP income.", "figure": "20%", "where": "General Instructions - Purpose of Form"}, {"fact": "Form 8995 is used when 2025 taxable income before the QBI deduction is at or below the threshold.", "figure": "$394,600 if married filing jointly, and $197,300 for all other returns", "where": "General Instructions - Who Can Take the Deduction"}, {"fact": "Within the phase-in range, only part of a specified service trade or business (SSTB) counts and Form 8995-A Schedule A is required.", "figure": "more than $394,600 but not more than $494,600 ... more than $197,300 but not more than $247,300", "where": "Exception 2"}, {"fact": "New for 2025: certain tip income may be excluded when figuring QBI.", "figure": null, "where": "What''s New - Excludable tip income"}]'::jsonb, 'For individuals and eligible estates/trusts with QBI below the threshold who are not patrons of specified agricultural or horticultural cooperatives. The 2026 instructions were not yet posted on the date checked.', '2026-11-26', 'draft', 'peace'),
  ('irs-i8995a', 'Instructions for Form 8995-A (2025)', 'IRS', 'Form 8995-A Instructions', 'https://www.irs.gov/instructions/i8995a', 'US-federal', 2025, '2025; Page Last Reviewed or Updated: 30-Apr-2026', array['qbi']::text[], 'Instructions for the full QBI deduction form used by taxpayers above the taxable income threshold or who are patrons of agricultural cooperatives. It explains the W-2 wage and property (UBIA) limitations and how specified service trades or businesses are phased out.', '[{"fact": "Form 8995-A is used when 2025 taxable income before the QBI deduction exceeds the threshold.", "figure": "more than $394,600 married filing jointly, and $197,300 for all other returns", "where": "General Instructions - Who Can Take the Deduction"}, {"fact": "Above the threshold, QBI may be limited to the greater of a W-2 wage amount or a wage-plus-property amount.", "figure": "50% of W-2 wages ... or 25% of W-2 wages plus 2.5% of the UBIA of qualified property", "where": "Determining Your QBI Deduction"}, {"fact": "The total deduction is limited to a percentage of taxable income (before the QBI deduction) minus net capital gain.", "figure": "20% of your taxable income", "where": "General Instructions - Purpose of Form"}, {"fact": "Specified service trades or businesses are generally excluded once taxable income exceeds the threshold plus the phase-in range.", "figure": null, "where": "Determining Your QBI Deduction"}]'::jsonb, 'For taxpayers above the threshold or cooperative patrons. The 2026 instructions were not yet posted on the date checked.', '2026-11-26', 'draft', 'peace'),
  ('irs-i1040sse', 'Instructions for Schedule SE (Form 1040) (2026)', 'IRS', 'Schedule SE Instructions', 'https://www.irs.gov/instructions/i1040sse', 'US-federal', 2026, '2026; Page Last Reviewed or Updated: 04-Nov-2026', array['self-employment-tax']::text[], 'Explains who must file Schedule SE and how to figure self-employment tax, including special rules for church employees, ministers, spouses, community income, and the optional methods. This is the 2026 edition, already posted.', '[{"fact": "Maximum self-employment income subject to social security tax for 2026.", "figure": "$184,500", "where": "What''s New"}, {"fact": "You must pay SE tax if net earnings from self-employment reach a minimum amount.", "figure": "$400 or more", "where": "General Instructions - Who Must File Schedule SE / Self-Employed Persons"}, {"fact": "Church employee income threshold for SE tax.", "figure": "$108.28 or more", "where": "General Instructions - Employees of Churches and Church Organizations"}, {"fact": "The optional methods may help some people qualify for certain credits when net earnings are below a threshold.", "figure": "$7,560", "where": "Line Instructions - How the Optional Methods Can Help You"}]'::jsonb, 'Applies to self-employed individuals, including sole proprietors, partners, and LLC members taxed as such.', '2026-11-26', 'draft', 'peace'),
  ('irs-f1040es-2026', 'Form 1040-ES (2026), Estimated Tax for Individuals', 'IRS', 'Form 1040-ES', 'https://www.irs.gov/pub/irs-pdf/f1040es.pdf', 'US-federal', 2026, 'Form 1040-ES (2026)', array['estimated-tax','self-employment-tax']::text[], 'The 2026 estimated tax package for individuals, including self-employed people, explaining who must pay estimated tax, the safe-harbor rules, due dates, and a worksheet. The IRS About Form 1040-ES page (https://www.irs.gov/forms-pubs/about-form-1040-es) lists two 2026 corrections (Feb. 2026).', '[{"fact": "Estimated payments are generally required if you expect to owe at least a set amount for 2026 after withholding and credits.", "figure": "at least $1,000", "where": "General Rule"}, {"fact": "Safe harbor: pay the smaller of a percentage of 2026 tax or of 2025 tax; filers whose 2025 AGI exceeded the stated threshold use 110% instead of 100% of prior-year tax.", "figure": "90% ... 100% ... 110% ... $150,000 ($75,000 if married filing separately for 2026)", "where": "General Rule / Higher income taxpayers"}, {"fact": "2026 payment due dates.", "figure": "April 15, 2026; June 15, 2026; Sept. 15, 2026; Jan. 15, 2027", "where": "Payment Due Dates"}, {"fact": "The January payment can be skipped if the 2026 return is filed and fully paid by an early date.", "figure": "February 1, 2027", "where": "Payment Due Dates (footnote)"}, {"fact": "Farmers and fishers substitute a lower percentage (66 2/3%, shown as \"662/3%\" in the PDF text extraction) for the 90% rule.", "figure": "662/3%", "where": "Special Rules - Farming and fishing"}]'::jsonb, 'Applies to individuals with income not subject to withholding; there is an exception if you had no tax liability for 2025. A 2027 version was not yet posted when checked.', '2026-11-26', 'draft', 'peace'),
  ('irs-newsroom-2026-inflation-adjustments', 'IRS releases tax inflation adjustments for tax year 2026, including amendments from the One, Big, Beautiful Bill', 'IRS', 'IR-2025-103 (Rev. Proc. 2025-32)', 'https://www.irs.gov/newsroom/irs-releases-tax-inflation-adjustments-for-tax-year-2026-including-amendments-from-the-one-big-beautiful-bill', 'US-federal', 2026, 'IR-2025-103, Oct. 9, 2025', array['deductions','payroll']::text[], 'IRS announcement of tax year 2026 inflation adjustments for more than 60 provisions, detailed in Revenue Procedure 2025-32. These amounts generally apply to returns filed in 2027.', '[{"fact": "2026 standard deduction amounts: married filing jointly, single/married filing separately, and head of household.", "figure": "$32,200 ... $16,100 ... $24,150", "where": "Standard Deduction"}, {"fact": "Top 37% bracket threshold for 2026.", "figure": "$640,600 ($768,700 for married couples filing jointly)", "where": "Marginal Rates"}, {"fact": "Employer-provided childcare credit maximum increased for 2026.", "figure": "$500,000 ($600,000 if the employer is an eligible small business)", "where": "Employer-Provided Childcare Tax Credit"}, {"fact": "Monthly qualified transportation fringe and qualified parking limit for 2026.", "figure": "$340", "where": "Qualified Transportation Fringe Benefit"}, {"fact": "Health FSA salary reduction limit for 2026.", "figure": "$3,400", "where": "Health Flexible Spending Cafeteria Plans"}]'::jsonb, 'Amounts apply to tax year 2026. The release does not list section 179 for 2026 in the fetched text; that figure comes from Pub 946''s What''s New for 2026.', '2026-11-26', 'draft', 'peace'),
  ('irs-newsroom-2027-inflation-adjustments', 'IRS releases tax inflation adjustments for tax year 2027; taxpayers continue to benefit from the Working Families Tax Cuts', 'IRS', 'IR-2026-133 (Rev. Proc. 2026-35)', 'https://www.irs.gov/newsroom/irs-releases-tax-inflation-adjustments-for-tax-year-2027-taxpayers-continue-to-benefit-from-the-working-families-tax-cuts', 'US-federal', 2027, 'IR-2026-133, Nov. 5, 2026', array['deductions','depreciation']::text[], 'IRS announcement of tax year 2027 inflation adjustments (Revenue Procedure 2026-35), released November 2026. It also confirms several 2026 comparison figures such as the 2026 section 179 limit.', '[{"fact": "Section 179 expensing limit for 2027, compared with 2026.", "figure": "$2,640,000 of section 179 property, up from $2,560,000 for tax year 2026", "where": "Expensing"}, {"fact": "SUV limit for section 179.", "figure": "$33,100, up from $32,000 for tax year 2026", "where": "Expensing"}, {"fact": "2027 standard deduction for married filing jointly.", "figure": "$33,200", "where": "Standard Deduction"}, {"fact": "Monthly qualified transportation fringe and parking limit for 2027.", "figure": "$350", "where": "Qualified Transportation Fringe Benefit"}]'::jsonb, 'Applies to tax year 2027 (returns filed in 2028); included as forward-looking context.', '2026-11-26', 'draft', 'peace'),
  ('sba-fund-your-business', 'Fund your business', 'SBA', null, 'https://www.sba.gov/business-guide/plan-your-business/fund-your-business', 'US-federal', null, null, array['funding']::text[], 'SBA overview of ways to fund a new business: self-funding (bootstrapping), venture capital and angel investors, crowdfunding, and small business loans, including SBA-guaranteed loans found through Lender Match. It also introduces SBA investment programs (SBIC, SBIR, STTR).', '[{"fact": "Self-funding keeps full control but puts all the risk on the owner; early retirement account withdrawals can bring fees or penalties.", "figure": null, "where": "Fund your business yourself with self-funding"}, {"fact": "Venture capital is usually exchanged for equity and an active role; most VCs want at least a board seat.", "figure": null, "where": "Get venture capital from investors"}, {"fact": "Lenders typically want a business plan, an expense sheet, and financial projections.", "figure": "financial projections for the next five years", "where": "Get a small business loan"}, {"fact": "SBA can guarantee a loan to reduce lender risk when a traditional loan is hard to get.", "figure": null, "where": "Use Lender Match to find lenders who offer SBA-guaranteed loans"}]'::jsonb, 'General guidance; specific program eligibility depends on SBA size standards and lender requirements.', '2026-11-26', 'draft', 'peace'),
  ('sba-7a-loans', '7(a) loans', 'SBA', '7(a) loan program', 'https://www.sba.gov/funding-programs/loans/7a-loans', 'US-federal', null, null, array['funding','expansion']::text[], 'Describes SBA''s primary business loan program, in which SBA guarantees loans made by participating lenders for working capital, equipment, real estate, refinancing, and changes of ownership. It also outlines the 7(a) Working Capital Pilot line-of-credit program.', '[{"fact": "Maximum 7(a) loan amount.", "figure": "$5 million", "where": "What is a 7(a) loan?"}, {"fact": "Borrowers must be operating for-profit U.S. businesses that are small under SBA size standards, creditworthy, and unable to get the credit on reasonable terms elsewhere.", "figure": null, "where": "Am I eligible?"}, {"fact": "7(a) Working Capital Pilot guarantee percentage depends on loan size.", "figure": "85% $150,000 or less; 75% if greater than $150,000", "where": "7(a) WCP - What are the terms?"}, {"fact": "7(a) WCP maximum maturity.", "figure": "60 months", "where": "7(a) WCP - What are the terms?"}, {"fact": "Applications go through a lender, not SBA directly.", "figure": null, "where": "How do I apply?"}]'::jsonb, 'For eligible small businesses; terms vary by lender, loan size, and loan type.', '2026-11-26', 'draft', 'peace'),
  ('sba-establish-business-credit', 'Establish business credit', 'SBA', null, 'https://www.sba.gov/business-guide/plan-your-business/fund-your-business', 'US-federal', null, null, array['business-credit','funding']::text[], 'SBA guidance on building and monitoring personal and business credit, since poor credit history is a common reason small business loan applications are declined. It covers getting a D-U-N-S number and checking business credit reports.', '[{"fact": "Loan eligibility for a new business is typically based on the owner''s personal credit score.", "figure": null, "where": "Maintain good personal and business credit history"}, {"fact": "A D-U-N-S number is a unique ID assigned to each physical business location.", "figure": "nine-digit", "where": "Apply for business credit"}, {"fact": "Business credit reports can be obtained from Experian, Equifax, Dun & Bradstreet and others; personal reports from Annual Credit Report.", "figure": null, "where": "Check and monitor your credit"}]'::jsonb, 'General guidance; this content is a section of the SBA ''Plan your business'' page reached via the fetched URL.', '2026-11-26', 'draft', 'peace'),
  ('sba-manage-your-finances', 'Manage your finances', 'SBA', null, 'https://www.sba.gov/business-guide/manage-your-business/manage-your-finances', 'US-federal', null, null, array['financial-statements','cash-flow']::text[], 'SBA basics on business finances: using a balance sheet, cost-benefit analysis, choosing the cash or accrual accounting method, GAAP, and getting help from a CPA, bookkeeper, or online service.', '[{"fact": "The balance sheet is described as the foundation of managing finances and a snapshot used for tracking assets, liabilities, equity and cash flow projections.", "figure": null, "where": "Start with a balance sheet"}, {"fact": "Cash method records a sale when payment is received; accrual records it when the sale is completed.", "figure": null, "where": "Pick a method of accounting"}, {"fact": "Worked cost-benefit example: added outdoor seating brings more new sales than new permit and equipment costs.", "figure": "$5,000 in new sales ... $3,000 in permitting and equipment expenses", "where": "Cost-benefit analysis (CBA)"}, {"fact": "Private companies aren''t required to follow GAAP.", "figure": null, "where": "GAAP"}]'::jsonb, 'General educational guidance; tax accounting method rules come from the IRS (see Pub 334 and Pub 583).', '2026-11-26', 'draft', 'peace'),
  ('sba-expand-new-locations', 'Expand to new locations', 'SBA', null, 'https://www.sba.gov/business-guide/grow-your-business/expand-new-locations', 'US-federal', null, null, array['expansion','funding']::text[], 'SBA guidance on growing into new markets: updating the marketing plan and financial forecast, legal steps like foreign qualification and new licenses, sales tax nexus, and franchising. The same page''s ''Get more funding'' section covers preparing financial statements, valuations and forecasts for lenders or investors.', '[{"fact": "Before expanding, update the marketing plan and build a forecast of costs and revenue for the new location.", "figure": null, "where": "Prepare for a new market"}, {"fact": "Doing business in a new state may require foreign qualification by filing a Certificate of Authority, often with a Certificate of Good Standing.", "figure": null, "where": "Legal steps to expand your business - Foreign qualification"}, {"fact": "A physical or economic presence (nexus) in a state can create a duty to collect that state''s sales tax.", "figure": null, "where": "Pay taxes for online sales"}, {"fact": "For more funding, prepare a business case, historical financial statements, a business credit report, a valuation, and a forecast; selling ownership dilutes current owners.", "figure": null, "where": "Get more funding (same page)"}]'::jsonb, 'State and local rules differ; the fetched URL redirected to the SBA ''Grow your business'' page.', '2026-11-26', 'draft', 'peace'),
  ('sba-close-or-sell-your-business', 'Close or sell your business', 'SBA', null, 'https://www.sba.gov/business-guide/manage-your-business/close-or-sell-your-business', 'US-federal', null, null, array['succession']::text[], 'SBA guidance on exiting a business: steps to close, business valuation and sales agreements, options for transferring ownership (outright sale, gradual sale, lease), and bankruptcy or liquidation.', '[{"fact": "Closing steps include deciding to close, filing dissolution documents, canceling registrations, meeting employment law obligations, resolving tax obligations (including canceling the EIN), and keeping records.", "figure": null, "where": "Close your business"}, {"fact": "Common guidance is to keep records for a range of years after closing.", "figure": "three to seven years", "where": "Close your business - Maintain records"}, {"fact": "Common valuation methods are the income approach, market approach, and asset approach.", "figure": null, "where": "Sell your business"}, {"fact": "Ownership can be transferred by outright sale, gradual sale (payments over time), or lease agreement.", "figure": null, "where": "Transfer ownership"}, {"fact": "Transferring a family business can trigger estate and gift tax obligations.", "figure": null, "where": "Transfer ownership - Other considerations"}]'::jsonb, 'General guidance; SBA recommends attorneys, accountants, and appraisers for specifics.', '2026-11-26', 'draft', 'peace')
